const msg = $json.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (!msg) return [];
const from = msg.from;
const text = (msg.text?.body || '').toLowerCase();
let reply = `Namaste! 🙏 Welcome to ${$env.BRAND_NAME || 'our showroom'}. Reply:\n1️⃣ PRICE — today's gold rate\n2️⃣ CATALOG — see designs\n3️⃣ VISIT — book an appointment`;
if (/price|rate|1/.test(text)) reply = `Today's rate (per gram):\n22K: ₹${$env.RATE_22K || '—'}\n24K: ₹${$env.RATE_24K || '—'}\n3% GST extra. Making charges vary by design. Reply VISIT to book a viewing.`;
else if (/catalog|design|2/.test(text)) reply = `Browse our latest designs here: ${$env.CATALOG_LINK || 'https://instagram.com/yourbrand'}\nTell us what you like — we will keep it ready at the showroom. 💛`;
else if (/visit|appoint|book|3/.test(text)) reply = `We would love to welcome you! Share a day & time that suits you, and our team will confirm your private viewing. 🪑✨`;
return [{ json: { from, reply } }];
